namespace Tsumo.Cli
{
    public class ResourceData
    {
        public string Integrity;
        public ResourceData(string integrity)
        {
            this.Integrity = integrity;
        }
    }
    public class ImageDimensions
    {
        public int width;
        public int height;
        public ImageDimensions(int width, int height)
        {
            this.width = width;
            this.height = height;
        }
    }
    public class Resource
    {
        public string id;
        public string? sourcePath;
        public bool publishable;
        public string? outputRelPath;
        public Tsonic.CSharp.Node.Buffer bytes;
        public string? text;
        public ResourceData Data;
        public string mediaType;
        public int width;
        public int height;
        public Resource(string id, string? sourcePath, bool publishable, string? outputRelPath, Tsonic.CSharp.Node.Buffer bytes, string? text, ResourceData data, string mediaType = "", int width = 0, int height = 0)
        {
            this.id = id;
            this.sourcePath = sourcePath;
            this.publishable = publishable;
            this.outputRelPath = outputRelPath;
            this.bytes = bytes;
            this.text = text;
            this.Data = data;
            this.mediaType = mediaType;
            this.width = width;
            this.height = height;
        }
    }
}
